(()=>{const view=document.getElementById('sector-view'),title=document.getElementById('sector-title');if(!view||!title)return;const sync=()=>view.classList.toggle('operations-layout-pilot',title.textContent.trim()==='Diretor de Operações');new MutationObserver(sync).observe(title,{childList:true,characterData:true,subtree:true});sync()})();
